const WORDS_PER_GROUP = 3;
const MAX_CHARS_PER_LINE = 22;
const HIGHLIGHT_COLOR = "&H00FFFF&"; // Amarelo no ASS (BGR invertido)
const BASE_COLOR = "&H00FFFFFF&";   // Branco

const items = $input.all();
const sourceItems = $('Baixar Vídeo Original').all();
const results = [];

function formatTime(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  const c = Math.round((seconds % 1) * 100);
  return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}.${c.toString().padStart(2, '0')}`;
}

function smartBreak(text, maxLen) {
  if (text.length <= maxLen) return text;
  const words = text.split(' ');
  const mid = Math.ceil(words.length / 2);
  return `${words.slice(0, mid).join(' ')}\\N${words.slice(mid).join(' ')}`;
}

// Aplica cores: primeira palavra do grupo em destaque, resto em branco
function applyHighlight(words) {
  return words.map((w, idx) => {
    const color = idx === 0 ? HIGHLIGHT_COLOR : BASE_COLOR;
    // Tag de estilo inline + palavra + reset de estilo
    return `{\\c${color}\\b1}${w.word}{\\r}`;
  }).join(' ');
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const source = sourceItems[i] ?? sourceItems[0];

  if (!source?.binary?.data) {
    throw new Error('Binário "data" não encontrado.');
  }

  let words = item.json.words;
  if (!Array.isArray(words) || words.length === 0) {
    throw new Error('Array "words" vazio.');
  }

  words.sort((a, b) => a.start - b.start);

  // CABEÇALHO ASS COM ESTILO MODERNO
  let assContent = `[Script Info]
Title: Viral Lyrics by n8n
ScriptType: v4.00+
PlayResX: 1080
PlayResY: 1920
WrapStyle: 0

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,Roboto,80,&H00FFFFFF,&H000000FF,&H00000000,&H80000000,1,0,0,0,100,100,2,0,1,4,3,2,30,30,200,1
Style: Highlight,Roboto,80,&H00FFFF00,&H000000FF,&H00000000,&H80000000,1,0,0,0,100,100,2,0,1,4,3,2,30,30,200,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
`;

  for (let j = 0; j < words.length; j += WORDS_PER_GROUP) {
    const group = words.slice(j, j + WORDS_PER_GROUP);

    let start = group[0].start;
    let end = group[group.length - 1].end;
    if (start >= end) end = start + 0.6;

    const startStr = formatTime(start);
    const endStr = formatTime(end);

    const rawText = group.map(w => w.word).join(' ');
    const brokenText = smartBreak(rawText, MAX_CHARS_PER_LINE);

    // Aplica destaque colorido
    const highlightedText = applyHighlight(group);

    // Adiciona emoji temático baseado no conteúdo (opcional)
    let emoji = '';
    const textLower = rawText.toLowerCase();
    if (textLower.includes('beijo') || textLower.includes('boca')) emoji = '💋 ';
    else if (textLower.includes('veneno')) emoji = '🐍 ';
    else if (textLower.includes('cama')) emoji = '🛏️ ';
    else if (textLower.includes('fogo') || textLower.includes('fogo')) emoji = '🔥 ';

    const finalText = `${emoji}${highlightedText}`;

    assContent += `Dialogue: 0,${startStr},${endStr},Default,,0,0,0,,${finalText}\n`;
  }

  results.push({
    json: { assContent, fileName: 'lyrics.ass' },
    binary: source.binary
  });
}

return results;

// SOLUÇÃO PARA DADOS BINÁRIOS: Em vez de usar Merge, pegamos o binário 
// do nó de download e o anexamos ao resultado do sub-workflow.

const assResult = $input.first().json; // { assContent: "..." }
